import { existsSync, readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const seedPath = join(here, "../../data/pf2e/skill-actions.json");
const generatedDir = join(here, "../../data/pf2e/generated");

/** Unified rule record (generated by `npm run data:pf2e` or from the seed). */
export interface RuleRecord {
  name: string;
  category: string;
  traits?: string[];
  level?: number | null;
  rarity?: string | null;
  text: string;
  source: string;
  /** Foundry actionType: "action" | "reaction" | "free" | "passive" (absent in seed/old data). */
  actionType?: string | null;
  /** Number of actions (1|2|3) when actionType is "action". */
  actionCost?: number | null;
  /** Use limit ("once per round/day"): per is "round"|"turn"|"day"|ISO-8601 ("PT1H"). */
  frequency?: { max: number; per: string };
  /** Weapons (incl. alchemical bombs): structured damage from the Foundry doc. */
  damage?: { dice: number; die: string; type: string };
  /** Built-in persistent damage (e.g. alchemist's fire). */
  persistent?: { number: number; faces: number | null; type: string };
  /** Splash damage value, when > 0. */
  splash?: number;
  /** Item bonus to attack rolls, when != 0. */
  bonus?: number;
  /** Range in feet for thrown/ranged weapons. */
  range?: number;
  /** Weapon proficiency category: "simple" | "martial" | "advanced" | "unarmed". */
  weaponCategory?: string;
  /** Creatures (bestiary): structured statblock — real AC/HP/saves/attacks.
   *  Present only when the importer resolved AC and HP (honest absence). */
  statblock?: CreatureStatblock;
}

/** An NPC Strike (Foundry "melee" item — ranged attacks included). */
export interface CreatureAttack {
  name: string;
  /** Attack bonus (system.bonus.value). */
  bonus: number;
  /** Damage entries in statblock order; category "persistent" preserved for PR2. */
  damage: { formula: string; type: string; category?: string }[];
  traits: string[];
  /** Present when the strike is ranged (system.range.increment). */
  rangeIncrement?: number;
  /** attackEffects (grab, knockdown…) — stored, not yet enforced. */
  effects?: string[];
}

/** An NPC ability ("action" item: passives, reactions, special actions). */
export interface CreatureAbility {
  name: string;
  actionType: string; // "action" | "reaction" | "free" | "passive"
  actions: number | null;
  text: string;
}

/** An NPC spellcasting entry (DC/attack + granted spell list). */
export interface CreatureSpellcasting {
  name: string;
  tradition: string;
  type: string; // "prepared" | "spontaneous" | "innate" | "focus"
  dc: number;
  attack: number;
  spells: { name: string; rank: number }[];
}

export interface CreatureStatblock {
  ac: number;
  hp: number;
  perception: number;
  saves: { fortitude: number; reflex: number; will: number };
  abilities?: Record<string, number>;
  speed?: { land: number; other: { type: string; value: number }[] };
  size?: string;
  senses?: string[];
  immunities?: string[];
  weaknesses?: { type: string; value: number }[];
  resistances?: { type: string; value: number }[];
  attacks: CreatureAttack[];
  abilitiesList: CreatureAbility[];
  spellcasting?: CreatureSpellcasting[];
}

interface SeedAction {
  id: string;
  name: string;
  skill: string;
  summary: string;
  criticalSuccess?: string;
  success?: string;
  failure?: string;
  criticalFailure?: string;
}

let index: RuleRecord[] | null = null;
let byName: Map<string, RuleRecord> | null = null;
let sourceLabel = "seed";

function normalize(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .trim();
}

function loadSeed(): RuleRecord[] {
  try {
    const data = JSON.parse(readFileSync(seedPath, "utf8")) as {
      actions: SeedAction[];
    };
    return data.actions.map((a) => ({
      name: a.name,
      category: "actions",
      text: [
        a.summary,
        a.criticalSuccess ? `Critical success: ${a.criticalSuccess}` : "",
        a.success ? `Success: ${a.success}` : "",
        a.failure ? `Failure: ${a.failure}` : "",
        a.criticalFailure ? `Critical failure: ${a.criticalFailure}` : "",
      ]
        .filter(Boolean)
        .join(" "),
      source: "seed",
    }));
  } catch {
    return [];
  }
}

function loadGenerated(): RuleRecord[] {
  const out: RuleRecord[] = [];
  for (const file of readdirSync(generatedDir)) {
    if (!file.endsWith(".json")) continue;
    try {
      const arr = JSON.parse(
        readFileSync(join(generatedDir, file), "utf8"),
      ) as RuleRecord[];
      // Só registros COMPLETOS entram no índice: um .json auxiliar largado na
      // pasta (ex.: feats-classified.json, sem `text`) poluía o lookup com
      // milhares de regras vazias — o modelo consultava e recebia nada.
      out.push(
        ...arr.filter((r) => r && typeof r.name === "string" && r.category && r.text),
      );
    } catch {
      // ignore invalid file
    }
  }
  return out;
}

function load(): RuleRecord[] {
  if (index) return index;
  if (existsSync(generatedDir)) {
    index = loadGenerated();
    sourceLabel = `foundry-generated (${index.length} entries)`;
  }
  if (!index || index.length === 0) {
    index = loadSeed();
    sourceLabel = "seed (run `npm run data:pf2e` for the full dataset)";
  }
  byName = new Map();
  for (const r of index) {
    const key = normalize(r.name);
    // Keep the first (avoids overwriting with same-named variants).
    if (!byName.has(key)) byName.set(key, r);
  }
  return index;
}

/**
 * Looks up a rule by name (any category). Strategy: exact name → substring →
 * highest token overlap. Returns the best match or `null`.
 */
export function lookupLocalRule(query: string): RuleRecord | null {
  const all = load();
  const q = normalize(query);
  if (!q) return null;

  // 1. Exact name.
  const exact = byName!.get(q);
  if (exact) return exact;

  // 2. Substring (prefers the shortest name = most specific match).
  let best: RuleRecord | null = null;
  let bestLen = Infinity;
  for (const r of all) {
    const n = normalize(r.name);
    if (n.includes(q) || q.includes(n)) {
      if (n.length < bestLen) {
        best = r;
        bestLen = n.length;
      }
    }
  }
  if (best) return best;

  // 3. Token overlap.
  const qTokens = new Set(q.split(/\s+/).filter((t) => t.length > 2));
  if (qTokens.size === 0) return null;
  let bestScore = 0;
  for (const r of all) {
    const nTokens = normalize(r.name).split(/\s+/);
    let score = 0;
    for (const t of nTokens) if (qTokens.has(t)) score++;
    if (score > bestScore) {
      bestScore = score;
      best = r;
    }
  }
  return bestScore > 0 ? best : null;
}

export function datasetSource(): string {
  load();
  return sourceLabel;
}

let activityCosts: Map<string, number> | null = null;

/**
 * Detects a MULTI-action activity (feat/action, actionType "action", cost ≥ 2)
 * mentioned inside free text (a roll's reason). Returns its canonical
 * lowercase name and cost, or null. Used by the engine to charge an
 * activity's FULL cost even when the model forgets to pass it — the model
 * naming the activity in `reason` is far more reliable than it passing a
 * separate cost argument. Names < 6 chars are skipped (false-positive prone).
 */
export function multiActionCost(
  text: string,
): { name: string; cost: number } | null {
  if (!activityCosts) {
    activityCosts = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.actionType === "action" &&
        (r.actionCost ?? 0) >= 2 &&
        r.name.length >= 6
      ) {
        activityCosts.set(r.name.toLowerCase(), r.actionCost!);
      }
    }
  }
  const t = text.toLowerCase();
  for (const [name, cost] of activityCosts) {
    if (t.includes(name)) return { name, cost };
  }
  return null;
}

let equipmentByName: Map<string, RuleRecord> | null = null;

/** Strips rune/quality prefixes so "+1 Striking Dagger" matches "Dagger". */
function baseItemName(name: string): string {
  return normalize(
    name.replace(/^\+\d+\s+/, "").replace(/^(striking|greater striking|major striking)\s+/i, ""),
  );
}

/**
 * Finds an equipment record by item name (exact → rune-stripped → the dataset
 * variant convention "Name (Lesser)" → substring). Backbone of the engine's
 * item grounding: traits, real damage, splash, range all come from here.
 */
export function itemRecord(name: string): RuleRecord | null {
  if (!equipmentByName) {
    equipmentByName = new Map();
    for (const r of load()) {
      if (r.category !== "equipment") continue;
      const key = normalize(r.name);
      if (!equipmentByName.has(key)) equipmentByName.set(key, r);
    }
  }
  const q = baseItemName(name);
  if (!q) return null;
  const exact = equipmentByName.get(q) ?? equipmentByName.get(normalize(name));
  if (exact) return exact;
  // Variant convention: consumables come as "Alchemist's Fire (Lesser)" etc.
  // A bare "alchemist's fire" should hit the weakest variant.
  for (const variant of ["lesser", "minor", "moderate", "greater", "major"]) {
    const v = equipmentByName.get(`${q} (${variant})`);
    if (v) return v;
  }
  // Substring, preferring the shortest (most specific) name.
  let best: RuleRecord | null = null;
  let bestLen = Infinity;
  for (const [n, r] of equipmentByName) {
    if ((n.includes(q) || q.includes(n)) && n.length < bestLen) {
      best = r;
      bestLen = n.length;
    }
  }
  return best;
}

/** Traits of an equipment item (empty when unknown). */
export function itemTraits(name: string): string[] {
  return itemRecord(name)?.traits ?? [];
}

let frequencies: Map<string, { max: number; per: string }> | null = null;

/**
 * Use-limit of a feat/action mentioned in free text ("Frequency once per
 * round"), keyed the same way as `multiActionCost`: the model naming the
 * activity in `reason`/`skill` is the trigger. Names < 6 chars are skipped.
 */
export function activityFrequency(
  text: string,
): { name: string; max: number; per: string } | null {
  if (!frequencies) {
    frequencies = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.frequency &&
        r.name.length >= 6
      ) {
        const key = r.name.toLowerCase();
        if (!frequencies.has(key)) frequencies.set(key, r.frequency);
      }
    }
  }
  const t = text.toLowerCase();
  for (const [name, f] of frequencies) {
    if (t.includes(name)) return { name, ...f };
  }
  return null;
}

let activeNames: Map<string, string> | null = null;

/**
 * An ACTIVE feat/action (actionType "action", cost ≥ 1) named inside free
 * text — used by the engine to notice the player invoked something with
 * rules that the model resolved as pure narration (Goblin Song case).
 * Returns the canonical name, or null. Names < 6 chars are skipped.
 */
export function namedActivity(text: string): string | null {
  if (!activeNames) {
    activeNames = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.actionType === "action" &&
        (r.actionCost ?? 0) >= 1 &&
        r.name.length >= 6
      ) {
        const key = r.name.toLowerCase();
        if (!activeNames.has(key)) activeNames.set(key, r.name);
      }
    }
  }
  const t = text.toLowerCase();
  for (const [key, name] of activeNames) {
    if (t.includes(key)) return name;
  }
  return null;
}

let requirementTexts: Map<string, string> | null = null;

/**
 * Requirements clause of a feat/action named in free text ("Requirements You
 * are wielding two melee weapons."). Same trigger convention as
 * `multiActionCost`: the model naming the activity. The engine validates only
 * a small whitelist of patterns it can answer from the sheet.
 */
export function activityRequirement(
  text: string,
): { name: string; requirement: string } | null {
  if (!requirementTexts) {
    requirementTexts = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.name.length >= 6 &&
        r.actionType &&
        r.actionType !== "passive"
      ) {
        const m = /Requirements\s+([^.;]+)[.;]/.exec(r.text);
        if (m?.[1]) {
          const key = r.name.toLowerCase();
          if (!requirementTexts.has(key)) requirementTexts.set(key, m[1].trim());
        }
      }
    }
  }
  const t = text.toLowerCase();
  for (const [name, requirement] of requirementTexts) {
    if (t.includes(name)) return { name, requirement };
  }
  return null;
}

let creaturesByName: Map<string, RuleRecord> | null = null;

/**
 * Normalizes a combatant/creature name into a bestiary query: drops the
 * engine's instance suffix ("Goblin Warrior 2"), parentheticals
 * ("Rat Swarm (Large)") and extra whitespace.
 */
function normalizeCreatureQuery(name: string): string {
  return normalize(name.replace(/\([^)]*\)/g, " ").replace(/\s+\d+\s*$/, ""))
    .replace(/\s+/g, " ")
    .trim();
}

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Whole-word containment: "giant rat" inside "ancient giant rat", not "rate". */
function wordBounded(hay: string, needle: string): boolean {
  return new RegExp(`(^|\\s)${escapeRegex(needle)}(\\s|$)`).test(hay);
}

/**
 * Finds a bestiary record WITH a structured statblock by creature name.
 * Strategy: exact → model-plural ("Giant Rats") → record name contained
 * whole-word in the query ("elite Goblin Warrior" → Goblin Warrior; shortest
 * wins). The REVERSE direction is deliberately not matched: a generic "Thug"
 * must never bind to a specific "Scarlet Triad Thug" (level 7) — unknown
 * names fall back to the level benchmark. Never matches across categories.
 */
export function creatureRecord(name: string): RuleRecord | null {
  if (!creaturesByName) {
    creaturesByName = new Map();
    for (const r of load()) {
      if (r.category !== "bestiary" || !r.statblock) continue;
      const key = normalize(r.name);
      if (!creaturesByName.has(key)) creaturesByName.set(key, r);
    }
  }
  const q = normalizeCreatureQuery(name);
  if (!q) return null;

  const exact = creaturesByName.get(q);
  if (exact) return exact;

  // The model often pluralizes ("three Giant Rats").
  const singular = q.replace(/s$/, "");
  if (singular !== q) {
    const s = creaturesByName.get(singular);
    if (s) return s;
  }

  // Longest record name contained in the query wins (most specific:
  // "elite Goblin Warrior" must hit "Goblin Warrior", not a bare "Goblin").
  let best: RuleRecord | null = null;
  let bestLen = 0;
  for (const [n, r] of creaturesByName) {
    if (n.length > bestLen && wordBounded(q, n)) {
      best = r;
      bestLen = n.length;
    }
  }
  return best;
}

let conditionNames: Set<string> | null = null;

/**
 * The official PF2e condition names (lowercase) from conditions.json — the
 * whitelist `update_state` validates against. Falls back to a hardcoded core
 * set when the generated dataset is absent (seed mode).
 */
export function officialConditions(): Set<string> {
  if (!conditionNames) {
    conditionNames = new Set(
      load()
        .filter((r) => r.category === "conditions")
        .map((r) => r.name.toLowerCase()),
    );
    if (conditionNames.size === 0) {
      conditionNames = new Set([
        "blinded", "clumsy", "concealed", "confused", "controlled", "dazzled",
        "deafened", "doomed", "drained", "dying", "encumbered", "enfeebled",
        "fascinated", "fatigued", "fleeing", "frightened", "grabbed", "hidden",
        "immobilized", "invisible", "off-guard", "paralyzed", "persistent damage",
        "petrified", "prone", "quickened", "restrained", "sickened", "slowed",
        "stunned", "stupefied", "unconscious", "wounded",
      ]);
    }
  }
  return conditionNames;
}
